  ["5304fd219434f619"] = { "Il cristallo è coperto di glifi e rune intricati. Non riesci a decifrarne nulla.", "." },
  ["530a6e20b8e1287d"] = { "%s va in pezzi e perde forza!", "." },
  ["530cb898c91293c9"] = { "Nella fenditura d'ombra Kor'ghan aspetta con cesoie più affilate della spada di una guardia.", "." },
  ["53113eeb88ce50fe"] = { "Elune, ascolta le mie preghiere. Concedici la serenità! Veglia sui nostri caduti...", "." },
  ["531c28079d2ed2fb"] = { "Nemmeno mio padre avrebbe potuto progettare una simile tragedia... un simile caos. Non ce la farai mai! Il tempo sta per scadere!", "." },
  ["531def31674efdfa"] = { "Risorgo dalla tomba per vendicarmi!", "." },
  ["5328da4adf8bb087"] = { "Salute, {class}. Sono un po' in difficoltà al momento: ho pochissime pelli.", "." },
  ["532a057abeed88bd"] = { "%s esamina il terreno e annuisce con approvazione.", "." },
  ["533248c695d73b98"] = { "Ottimo, {class}! Il nostro maestro dei campi di battaglia, Thelman Slatefist, si trova nelle sale delle udienze del re, nel Castello di ⟦Stormwind=Roccavento⟧. Ti aiuterà a raggiungere la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["53338fde5045f77c"] = { "Un tempo gioiello del Lordaeron settentrionale, la città di Stratholme è il luogo dove il principe Arthas si rivoltò contro il suo mentore, Uther Lightbringer, e massacrò centinaia dei suoi stessi sudditi, ritenuti contagiati dalla piaga della non morte. Poco dopo seguì la resa di Arthas al Re dei Lich. La città in rovina è ora abitata dal Flagello dei non morti, guidato dal potente lich Kel'Thuzad, e da un contingente di Crociati Scarlatti, guidati dal gran crociato Dathrohan. Le due parti sono impegnate in uno scontro continuo e violento.", "." },
  ["5333ee0f56e35191"] = { "So qualcosa, ma da qui a essere esperti ce ne passa. Per tua fortuna, Magar lo è. Si trova verso il retro della bottega. Vedi se può aiutarti, ma cerca di non farlo arrabbiare. È un tipo irritabile.", "." },
  ["53371757c5c8b517"] = { "Non approvo che tu sia ricorso all'alchimia per risolvere alcuni problemi, ma i risultati mi piacciono. Ottimo lavoro.", "." },
  ["53421fa25cad893e"] = { "Per raggiungere il traghetto di ⟦Rut'theran Village=Rut'theran⟧, devi andare a Darnassus e prendere il portale per ⟦Rut'theran Village=Rut'theran⟧, ai piedi di Teldrassil.", "." },
  ["5348e4d1faf5bb06"] = { "Vivo solo per servire, Capoguerra! Senza la tua guida la mia vita è vuota e priva di senso.", "." },
  ["534d4d999983d8a6"] = { "%s si contorce in agonia. Il Discepolo sembra riuscire a farsi strada.", "." },
  ["5354bf2d0785db08"] = { "Sei riuscit<o/a> ad addomesticare lo scorpide?", "." },
  ["5358d7d322332ff8"] = { "Vai alla Hall of the Brave. Lì troverai il Profanatore Deze Snowbane, che ti aiuterà a raggiungere il ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["535933a1c59debbb"] = { "Non so, Jill. Se Klaven scende mentre battiamo la fiacca, potremmo finire come una di quelle cose!", "." },
  ["535dc65e7afed0c1"] = { "Popolo dell'⟦Horde=Orda⟧, cittadini di Orgrimmar, venite, radunatevi e celebrate <un/una> <eroe/eroina> dell'⟦Horde=Orda⟧. In questo giorno, {name}, sotto gli auspici del nostro glorioso Capoguerra, ha inferto un colpo mortale allo Stormo dei Draghi Neri. La madre della covata, Onyxia, è stata uccisa!", "." },
  ["5365bdd2936c53fc"] = { "Salve, {class}!", "." },
  ["536bd20463608dcb"] = { "Quando le nostre scorte sono alte, il feldmaresciallo Teravaine è di stanza nel ⟦Field of Strife=Pian della Discordia⟧, presso la nostra postazione di baliste più a sud.", "." },
  ["53713b6aefa58b7a"] = { "Erbalismo", "." },
  ["537c3d154ddd4a22"] = { "La nostra evocazione è completa! Il cristallo Ash'ari è stato ripristinato!", "." },
  ["5386a3e1c87c56c5"] = { "Renderemo schiavi i verrospini!", "." },
  ["5388132562d5dd4d"] = { "Gloria a {name}, che difende il Popolo!", "." },
  ["538a985cf8cdd1d1"] = { "Brucia nel fuoco della giustizia!", "." },
  ["539218c5d69e7ac0"] = { "Sì, anch'io devo lasciare un po' di roba. La trovi andando a nord lungo la strada per Orgrimmar; poi chiedi a uno dei grunt che stanno lì.", "." },
  ["539f657aafaa2f8f"] = { "Vuoi fare un giro in grifone, eh? Dungar tiene i suoi uccelli sul bastione del ⟦Trade District=Quartiere del Commercio⟧. Ricordati solo di tenerti forte!", "." },
  ["53a03a5a757b7138"] = { "Ti interessa esplorare una di queste spedizioni?", "." },
  ["53a7c2af03d14388"] = { "Mostrami i tuoi grimori.", "." },
  ["53a95d9692f5d840"] = { "Vince la squadra rossa!", "." },
  ["53a9b4524a70a5ee"] = { "Lo giustizio secondo le istruzioni del mio signore, e lo faccio in modo che soffra atrocemente prima di morire, come punizione per i suoi crimini contro la mia gente.", "." },
  ["53b54413d73bdd6c"] = { "I tuoi progressi finora mi soddisfano. Di certo la Madre Terra ha ispirato le tue mani.", "." },
  ["53c20d008f110426"] = { "Basta vedere come stai in piedi per capire che non sei <un/una> <guerriero/guerriera>.\n\nPerché non vai a fare qualcosa di sicuro, tipo leggere un libro?", "." },
  ["53c806953261cf33"] = { "TENETE LA LINEA! NON FATE PASSARE NIENTE!", "." },
  ["53c84853ffcedfe8"] = { "È stato rinfrescante. Ora ci sono informazioni che vanno riferite...", "." },
  ["53c8a1cecfab7b9c"] = { "Hai sentito parlare del tram, eh? Che viaggio! Lo trovi nel Distretto dei Nani, verso il fondo. Ah, e ricordati di tenere braccia e gambe dentro il tram mentre è in movimento.", "." },
  ["53ca038aaa7b7c98"] = { "Soldati Horus, Tilling, Rockwell...", "." },
  ["53dc059d2e716321"] = { "Saluti! Custodisco l'ingresso. Usa i dischi appropriati per accedere a Uldum.", "." },
  ["53e00d4bf9f833ab"] = { "La miglior birra di ⟦Stormwind=Roccavento⟧, Langston. Grazie.", "." },
  ["53e4bc05d8f7ca51"] = { "Non capisco.", "." },
  ["53e7bc0b2042ede4"] = { "Stolti! Continuate a combattere, se è questo che volete! A ogni battaglia, altri di voi cadono e le schiere dei non morti si ingrossano!", "." },
  ["53eb8fa92fedb60a"] = { "|cffffff00La Torre di ⟦Plaguewood=Malaselva⟧ è stata presa dall'⟦Alliance=Alleanza⟧!|r", "." },
  ["53fd4406ce21c39e"] = { "Il segreto del coltello è tenerlo nascosto fino al momento di colpire.", "." },
